CREATE TABLE IF NOT EXISTS organization (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS site (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT site_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id));
CREATE TABLE IF NOT EXISTS location (id CHAR(36) PRIMARY KEY, site_id CHAR(36) NOT NULL, name VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT location_site_fk FOREIGN KEY (site_id) REFERENCES site(id));
CREATE TABLE IF NOT EXISTS person (id CHAR(36) PRIMARY KEY, national_id_ciphertext VARCHAR(1024) NOT NULL, national_id_lookup VARCHAR(128) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY person_national_id_lookup_unique (national_id_lookup));
CREATE TABLE IF NOT EXISTS employment_assignment (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, organization_id CHAR(36) NOT NULL, manager_person_id CHAR(36) NULL, effective_from DATETIME NOT NULL, effective_until DATETIME NULL, created_at DATETIME NOT NULL, KEY employment_assignment_active_index (person_id, effective_until), CONSTRAINT employment_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT employment_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id), CONSTRAINT employment_manager_fk FOREIGN KEY (manager_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS identity_link (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, issuer VARCHAR(512) NOT NULL, subject VARCHAR(512) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY identity_link_issuer_subject_unique (issuer, subject), CONSTRAINT identity_link_person_fk FOREIGN KEY (person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS local_account (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, username VARCHAR(255) NOT NULL, password_hash VARCHAR(1024) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY local_account_username_unique (username), CONSTRAINT local_account_person_fk FOREIGN KEY (person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS role (id CHAR(36) PRIMARY KEY, name VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS permission (id CHAR(36) PRIMARY KEY, code VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, UNIQUE KEY permission_code_unique (code));
CREATE TABLE IF NOT EXISTS role_assignment (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, role_id CHAR(36) NOT NULL, organization_id CHAR(36) NULL, created_at DATETIME NOT NULL, CONSTRAINT role_assignment_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT role_assignment_role_fk FOREIGN KEY (role_id) REFERENCES role(id), CONSTRAINT role_assignment_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id));
CREATE TABLE IF NOT EXISTS data_owner_assignment (id CHAR(36) PRIMARY KEY, module_code VARCHAR(255) NOT NULL, organization_id CHAR(36) NULL, person_id CHAR(36) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT data_owner_person_fk FOREIGN KEY (person_id) REFERENCES person(id), CONSTRAINT data_owner_organization_fk FOREIGN KEY (organization_id) REFERENCES organization(id));
CREATE TABLE IF NOT EXISTS delegation (id CHAR(36) PRIMARY KEY, delegator_person_id CHAR(36) NOT NULL, delegate_person_id CHAR(36) NOT NULL, module_code VARCHAR(255) NOT NULL, reason VARCHAR(1024) NOT NULL, effective_from DATETIME NOT NULL, effective_until DATETIME NOT NULL, created_at DATETIME NOT NULL, KEY delegation_active_index (delegate_person_id, effective_until), CONSTRAINT delegation_delegator_fk FOREIGN KEY (delegator_person_id) REFERENCES person(id), CONSTRAINT delegation_delegate_fk FOREIGN KEY (delegate_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS request (id CHAR(36) PRIMARY KEY, reference VARCHAR(64) NOT NULL, module_code VARCHAR(255) NOT NULL, requestor_person_id CHAR(36) NOT NULL, organization_snapshot VARCHAR(4096) NOT NULL, status VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, submitted_at DATETIME NULL, UNIQUE KEY request_reference_unique (reference), KEY request_workflow_queue_index (status, created_at), CONSTRAINT request_requestor_fk FOREIGN KEY (requestor_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS approval_step (id CHAR(36) PRIMARY KEY, request_id CHAR(36) NOT NULL, sequence VARCHAR(16) NOT NULL, assignee_snapshot VARCHAR(4096) NOT NULL, status VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT approval_step_request_fk FOREIGN KEY (request_id) REFERENCES request(id));
CREATE TABLE IF NOT EXISTS approval_decision (id CHAR(36) PRIMARY KEY, approval_step_id CHAR(36) NOT NULL, actor_person_id CHAR(36) NOT NULL, decision VARCHAR(64) NOT NULL, reason VARCHAR(2048) NULL, created_at DATETIME NOT NULL, CONSTRAINT approval_decision_step_fk FOREIGN KEY (approval_step_id) REFERENCES approval_step(id), CONSTRAINT approval_decision_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS audit_event (id CHAR(36) PRIMARY KEY, actor_person_id CHAR(36) NULL, action VARCHAR(255) NOT NULL, target_type VARCHAR(255) NOT NULL, target_id CHAR(36) NOT NULL, result VARCHAR(64) NOT NULL, metadata VARCHAR(8192) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT audit_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS attachment (id CHAR(36) PRIMARY KEY, object_key VARCHAR(1024) NOT NULL, content_type VARCHAR(255) NOT NULL, size_bytes VARCHAR(32) NOT NULL, created_by_person_id CHAR(36) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT attachment_creator_fk FOREIGN KEY (created_by_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS attachment_scan (id CHAR(36) PRIMARY KEY, attachment_id CHAR(36) NOT NULL, status VARCHAR(64) NOT NULL, scanned_at DATETIME NOT NULL, CONSTRAINT attachment_scan_attachment_fk FOREIGN KEY (attachment_id) REFERENCES attachment(id));
CREATE TABLE IF NOT EXISTS outbox_event (id CHAR(36) PRIMARY KEY, type VARCHAR(255) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, payload VARCHAR(8192) NOT NULL, occurred_at DATETIME NOT NULL, processed_at DATETIME NULL, UNIQUE KEY outbox_event_idempotency_unique (idempotency_key), KEY outbox_event_processing_index (processed_at, occurred_at));
CREATE TABLE IF NOT EXISTS notification (id CHAR(36) PRIMARY KEY, outbox_event_id CHAR(36) NOT NULL, channel VARCHAR(64) NOT NULL, recipient_person_id CHAR(36) NOT NULL, delivered_at DATETIME NULL, created_at DATETIME NOT NULL, CONSTRAINT notification_outbox_fk FOREIGN KEY (outbox_event_id) REFERENCES outbox_event(id), CONSTRAINT notification_recipient_fk FOREIGN KEY (recipient_person_id) REFERENCES person(id));
CREATE TABLE IF NOT EXISTS export_event (id CHAR(36) PRIMARY KEY, actor_person_id CHAR(36) NOT NULL, reason VARCHAR(2048) NOT NULL, scope VARCHAR(4096) NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT export_actor_fk FOREIGN KEY (actor_person_id) REFERENCES person(id));
